using FirstApp.Models;
using Microsoft.AspNetCore.Mvc;
using System.Linq;

namespace FirstApp.Controllers;

public class EmployeeController : Controller
{
    // ... Index and Create actions from above ...

    [HttpPost]
    public IActionResult Create(Employee employee)
    {
        if (ModelState.IsValid)
        {
            Repository.Create(employee);
            return View("Thanks", employee);
        }
        return View();
    }

    public IActionResult Update(string empname)
    {
        var employee = Repository.AllEmployees
            .FirstOrDefault(e => e.Name == empname);
        return View(employee);
    }

    [HttpPost]
    public IActionResult Update(Employee employee, string empname)
    {
        if (ModelState.IsValid)
        {
            var existing = Repository.AllEmployees
                .FirstOrDefault(e => e.Name == empname);
            if (existing != null)
            {
                existing.Age = employee.Age;
                existing.Salary = employee.Salary;
                existing.Department = employee.Department;
                existing.Sex = employee.Sex;
                existing.Name = employee.Name;
            }
            return RedirectToAction("Index");
        }
        return View();
    }

    [HttpPost]
    public IActionResult Delete(string empname)
    {
        var employee = Repository.AllEmployees
            .FirstOrDefault(e => e.Name == empname);
        if (employee != null)
        {
            Repository.Delete(employee);
        }
        return RedirectToAction("Index");
    }
}

using System.ComponentModel.DataAnnotations;

namespace FirstApp.Models;

public class Employee
{
    [Required(ErrorMessage = "Please enter your name")]
    public string Name { get; set; } = string.Empty;

    [Range(16, 60, ErrorMessage = "Age must be between 16 and 60")]
    public int Age { get; set; }

    [RegularExpression(@"\d+(\.\d{1,2})?",
        ErrorMessage = "Enter a valid salary, e.g. 50000 or 50000.50")]
    public decimal Salary { get; set; }

    public string Department { get; set; } = string.Empty;

    [RegularExpression(@"^[MF]+$",
        ErrorMessage = "Please select Male or Female")]
    public char Sex { get; set; }
}

